#!/bin/bash
set -euo pipefail

# VBench multi-GPU evaluation for videos generated by VAR-Q/InfinityStar.
# Expect prompt-based filenames: "<prompt_en>-<sample_idx>.mp4"
#
# Usage:
#   bash evaluation/run_vbench_parallel_varq.sh "0,1,2,3"

GPU_LIST="${1:-0,1,2,3,4,5,6,7}"
VIDEOS_PATH="${VIDEOS_PATH:-/home/jiaji_lu/AR/VAR-Q/Benchmark/outputs/vbench_eval_varq}"
RESULTS_DIR="${RESULTS_DIR:-/home/jiaji_lu/AR/VAR-Q/Benchmark/outputs/vbench_results_varq}"
MODEL_NAME="${MODEL_NAME:-infinitystar_varq_vbench}"
PYTHON_ENV="${PYTHON_ENV:-/home/jiaji_lu/conda/envs/vbench/bin/python}"
VBENCH_EVAL_SCRIPT="${VBENCH_EVAL_SCRIPT:-/home/jiaji_lu/WM/VBench/evaluate.py}"
VBENCH_SCORE_SCRIPT="${VBENCH_SCORE_SCRIPT:-/home/jiaji_lu/WM/VBench/scripts/cal_final_score.py}"

DIMENSIONS=(
  "subject_consistency"
  "background_consistency"
  "aesthetic_quality"
  "imaging_quality"
  "object_class"
  "multiple_objects"
  "color"
  "spatial_relationship"
  "scene"
  "temporal_style"
  "overall_consistency"
  "human_action"
  "temporal_flickering"
  "motion_smoothness"
  "dynamic_degree"
  "appearance_style"
)

if [ ! -d "$VIDEOS_PATH" ]; then
  echo "Videos path does not exist: $VIDEOS_PATH"
  exit 1
fi

first_video=$(ls "$VIDEOS_PATH"/*.mp4 2>/dev/null | head -1 || true)
if [ -z "$first_video" ]; then
  echo "No mp4 files found in: $VIDEOS_PATH"
  exit 1
fi

first_name=$(basename "$first_video")
if [[ "$first_name" =~ ^[0-9]{3}-[0-9]{2}\.mp4$ ]]; then
  echo "Detected ID-style filename: $first_name"
  echo "Note: Using vbench_standard mode with ID-style filenames."
  echo "      Prompts will be loaded from VBench standard prompt suite."
fi

mkdir -p "$RESULTS_DIR"/logs "$RESULTS_DIR"/status

IFS=',' read -ra GPUS <<< "$GPU_LIST"
NUM_GPUS="${#GPUS[@]}"
NUM_DIMS="${#DIMENSIONS[@]}"

echo "=========================================="
echo "VBench parallel evaluation (VARQ)"
echo "videos_path: $VIDEOS_PATH"
echo "results_dir: $RESULTS_DIR"
echo "model_name: $MODEL_NAME"
echo "gpu_list: $GPU_LIST"
echo "num_dims: $NUM_DIMS"
echo "num_gpus: $NUM_GPUS"
echo "=========================================="

declare -a QUEUE=()
for i in "${!DIMENSIONS[@]}"; do
  dim="${DIMENSIONS[$i]}"
  done_file="$RESULTS_DIR/status/${dim}.done"
  if [ ! -f "$done_file" ]; then
    QUEUE+=("$i")
  fi
done

if [ ${#QUEUE[@]} -eq 0 ]; then
  echo "All dimensions already done."
  exit 0
fi

declare -A RUNNING=()
TASK_COUNTER=0

start_task() {
  local task_idx=$1
  local gpu_id=$2
  local dim="${DIMENSIONS[$task_idx]}"
  local log_file="$RESULTS_DIR/logs/${dim}.log"
  local done_file="$RESULTS_DIR/status/${dim}.done"

  echo "[GPU $gpu_id] Start $dim"

  (
    export CUDA_VISIBLE_DEVICES=$gpu_id
    export MASTER_PORT=$((51000 + TASK_COUNTER))
    export MASTER_ADDR="localhost"
    export RANK="0"
    export LOCAL_RANK="0"
    export WORLD_SIZE="1"

    "$PYTHON_ENV" "$VBENCH_EVAL_SCRIPT" \
      --videos_path "$VIDEOS_PATH" \
      --output_path "$RESULTS_DIR" \
      --dimension "$dim" \
      --mode "vbench_standard" \
      --imaging_quality_preprocessing_mode "longer" \
      > "$log_file" 2>&1

    ec=$?
    if [ $ec -eq 0 ]; then
      touch "$done_file"
      echo "[GPU $gpu_id] Done $dim"
    else
      echo "[GPU $gpu_id] Failed $dim, exit=$ec"
    fi
  ) &

  RUNNING[$gpu_id]="$task_idx $!"
  TASK_COUNTER=$((TASK_COUNTER + 1))
}

is_idle() {
  local gpu_id=$1
  local info="${RUNNING[$gpu_id]:-}"
  if [ -z "$info" ]; then
    return 0
  fi
  local pid=$(echo "$info" | awk '{print $2}')
  if ! kill -0 "$pid" 2>/dev/null; then
    wait "$pid" 2>/dev/null || true
    unset RUNNING[$gpu_id]
    return 0
  fi
  return 1
}

# Initial fill
for gpu in "${GPUS[@]}"; do
  if [ ${#QUEUE[@]} -eq 0 ]; then
    break
  fi
  idx="${QUEUE[0]}"
  QUEUE=("${QUEUE[@]:1}")
  start_task "$idx" "$gpu"
  sleep 1
done

while [ ${#QUEUE[@]} -gt 0 ] || [ ${#RUNNING[@]} -gt 0 ]; do
  for gpu in "${GPUS[@]}"; do
    if is_idle "$gpu"; then
      if [ ${#QUEUE[@]} -gt 0 ]; then
        idx="${QUEUE[0]}"
        QUEUE=("${QUEUE[@]:1}")
        start_task "$idx" "$gpu"
      fi
    fi
  done
  sleep 5
done

echo "All dimensions finished, combine results..."
cd /home/jiaji_lu/AR/InfinityStar
python3 evaluation/combine_vbench_results.py \
  --results_dir "$RESULTS_DIR" \
  --model_name "$MODEL_NAME" \
  --dimensions "${DIMENSIONS[@]}"

ZIP_FILE="/tmp/${MODEL_NAME}_combined_results.zip"
cd "$RESULTS_DIR"
zip -r "$ZIP_FILE" "${MODEL_NAME}_combined_eval_results.json" >/dev/null 2>&1

if [ -f "$ZIP_FILE" ]; then
  "$PYTHON_ENV" "$VBENCH_SCORE_SCRIPT" \
    --zip_file "$ZIP_FILE" \
    --model_name "${MODEL_NAME}_combined"
  rm -f "$ZIP_FILE"
fi

echo "Done. Results: $RESULTS_DIR"
